import{_ as a,c as r,o as t,aB as i}from"./chunks/framework.uEqVN41L.js";const p=JSON.parse('{"title":"澳大利亚","description":"","frontmatter":{"title":"澳大利亚","author":"μ, hanbao","wordCount":1042},"headers":[],"relativePath":"overseas/australia.md","filePath":"overseas/australia.md","lastUpdated":1777910073000}'),n={name:"overseas/australia.md"};function o(l,e,s,d,h,c){return t(),r("div",null,e[0]||(e[0]=[i('<h2 id="重要工具" tabindex="-1">重要工具 <a class="header-anchor" href="#重要工具" aria-label="Permalink to &quot;重要工具&quot;">​</a></h2><p>在澳大利亚，此网站可以提供非常多的资讯 <a href="https://www.transhub.org.au/" target="_blank" rel="noreferrer">transhub.org.au</a>。其中 trans-friendly 的清单可能没有及时更新，因而可以去 <a href="https://www.reddit.com/r/transgenderau/" target="_blank" rel="noreferrer">r/transgenderau - Reddit</a> 上看一下大家的讨论，以获取更多信息。</p><h2 id="跨性别医疗资源" tabindex="-1">跨性别医疗资源 <a class="header-anchor" href="#跨性别医疗资源" aria-label="Permalink to &quot;跨性别医疗资源&quot;">​</a></h2><p>在澳大利亚，成年个体可以 informed consent (知情同意)，以获取激素代替疗法 / 性别肯定激素疗法。具体地，您可以联系当地有资质的医生，部分校医可能有资格，但若没有，则会转诊，可能带来一定的延误。具体获得荷尔蒙的速度部分取决于医生的友好程度，较快的情况下是在两三周内可以完成药物开具。此外，此类医生可以开具的药物类型主要是激素与拮抗剂，但对性别肯定手术仍然不算了解，所以可能无法提供更专业的建议。</p><p>同时，有部分案例反馈是严重精神状态可能会影响医生的开具意愿。</p><p>在澳大利亚本地进行性别确认手术（SRS）需要在激素代替疗法（HRT）进行至少 12 个月后，找精神科医生（psychiatrist）开具两份心理检测报告（mental assessment report）才可以开始排队 SRS</p><h3 id="hrt推荐gp" tabindex="-1">HRT 推荐 GP <a class="header-anchor" href="#hrt推荐gp" aria-label="Permalink to &quot;HRT推荐GP&quot;">​</a></h3><h4 id="墨尔本-维多利亚州" tabindex="-1">墨尔本，维多利亚州 <a class="header-anchor" href="#墨尔本-维多利亚州" aria-label="Permalink to &quot;墨尔本，维多利亚州&quot;">​</a></h4><ol><li>Medical Hub @ RMIT 的 Dr Ben Ooi，可用汉语官话（Mandarin）和粤语（Cantonese）交流，预约首诊时提出 HRT，会先帮你预约一次血液检测（Blood test），然后帮你约好复诊，如血液检测无明显异常且知情同意即可开具 HRT 处方，总耗时 2 星期不到。GP 诊断用 Medibank（留学生医保的一种）可部分报销，血液检测是免费的。</li><li>Box Hill Centro Clininc 的 Dr Ling Li 李医生，支持英语和普通话，非常 trans-friendly。第一次面诊之前要先给 clinic 打电话预约 Dr Ling Li 的 long consultation，就诊当天就可以做血检，clinic 里就有个检测中心，下次面诊的时候就能看到结果。Private billing, 有 Medicare 的话大概 AUD 36-37 的 out-of-pocket。</li><li>Equinox Clinic (<a href="https://equinox.org.au" target="_blank" rel="noreferrer">equinox.org.au</a>) 是墨尔本最大的 bulk billing 跨性别诊所。（2026 May update: 由于新患者排队太长，现已不接受新患者，可在诊所官网查看是否接收新患者）</li></ol><h3 id="生育力保存-fertility-preservation" tabindex="-1">生育力保存 Fertility Preservation <a class="header-anchor" href="#生育力保存-fertility-preservation" aria-label="Permalink to &quot;生育力保存 Fertility Preservation&quot;">​</a></h3><p>看第一次跟 GP 面诊时可以提出自己要做生育力保存（冻精），在墨尔本有两家较大的可以做生育力保存的机构：Melbourne IVF 和 Monash IVF. Monash IVF Clayton clinic 比较好预约到，向 GP 要一个 referral letter 写明因 Gender affirming care treatment 要进行生育力保存，再给 IVF clinic 前台打电话要到邮箱，把 referral letter 发给他们就可以预约男性生殖健康专科医生 Andrology specialist（如果只做冻精的话不需要约 specialist appointment），和 sperm freezing。 Monash IVF 做冻精的费用分为两部分：采集 collection fee 和寄存 storage fee. 采集费用一次性约 AUD 500，寄存费用每半年 AUD 320，以上皆为没有保险没有 Medicare 的全价。GP 开的 referrel letter 因为写明了是因为 gender affirming care，属于 Medicare 可以报销：采集费全免，寄存费减半到每半年 AUD 160.</p><h2 id="跨性别生活与学习环境" tabindex="-1">跨性别生活与学习环境 <a class="header-anchor" href="#跨性别生活与学习环境" aria-label="Permalink to &quot;跨性别生活与学习环境&quot;">​</a></h2><p>澳大利亚的学校的大部分信息系统可以使用 preferred name. 部分学校的宿舍是混住，因而宿舍问题也会少很多。 大学入学的登记表填写性别可以选择 male, female, others. 性别不会出现在之后大学生活的任何场合（除医疗），包括学生证上。可以选择自己的 pronoun，其他人也会尊重并遵守。</p><h3 id="墨尔本" tabindex="-1">墨尔本 <a class="header-anchor" href="#墨尔本" aria-label="Permalink to &quot;墨尔本&quot;">​</a></h3><p>已知皇家墨尔本理工大学（RMIT）有第三卫生间。 Monash University Clayton 校区，Victoria University Footscray Park 校区都有 queer room, 有各自 queer 群体组成的学生社团。</p>',15)]))}const f=a(n,[["render",o]]);export{p as __pageData,f as default};
